/**
 * Returns the local icon path for a team name, or null if not found.
 * Lookup is fully case-insensitive.
 */
export function getTeamIcon(teamName) {
  if (!teamName) return null;
  return TEAM_ICONS[teamName.toLowerCase()] || null;
}
